// BagItem — child contract holding one registered TON Storage bag.
//
// Deployed by BagRegistry (the master) with a deterministic address derived
// from (BagItem code, bag index, registry address). Lifecycle:
//
//   1. Deployed in the NotInitialized state (index + registry only).
//   2. Initialized exactly once by the registry's init message.
//   3. Afterwards, only the original uploader may deactivate it.
//   4. On deactivation, the residual balance is refunded to the uploader,
//      keeping only a tiny rent floor so the on-chain record persists.
//
// Audit fixes implemented here:
//   C4 — empty-body messages are accepted as top-ups before any other logic,
//        so the contract is always rechargeable.
//   H1 — DeactivateBag refunds the residual balance to the uploader so no
//        funds remain locked beyond a multi-decade rent floor.
//   M2 — init state is an EXPLICIT union discriminant, routed with `match`,
//        not a fragile `remainingRefsCount()` heuristic.
//   M3 — typed `contract` ABI declaration.
//   L3 — getters return clean sentinels (none-address, zeros) while
//        uninitialized, never a misleading placeholder address.

import "errors.tolk"
import "events.tolk"
import "messages.tolk"
import "storage.tolk"

// ===========================================================================
// ECONOMIC CONSTANTS
//
// DEACTIVATED_FLOOR keeps the item alive after DeactivateBag so the index
// stays queryable on-chain (`get_bag_data` returns `isActive: false`,
// `get_storage_metadata` keeps its data). 0.005 TON covers many decades of
// basechain storage rent for the typical metadata size.
// ===========================================================================

const DEACTIVATED_FLOOR: coins = ton("0.005")

// Mirror of the struct-attached opcode of `DeactivateBag` (messages.tolk).
// Used by the explicit opcode pre-check so an unknown body produces the
// standard TVM "unknown opcode" exit (0xFFFF) rather than the typed parser's
// prefix-mismatch code.
const OP_DEACTIVATE_BAG: int = 0x44454143

// ===========================================================================
// CONTRACT ABI DECLARATION (M3)
//
// Storage is the `BagItemData` union in BOTH states. The deployment shape is
// the union as well: the registry writes the pre-init data through the union
// serializer (`serializeBagItemData`), so the deployed cell always carries the
// 1-bit `Either` discriminant (tag 0 => NotInitialized). Declaring the bare
// `BagItemDataNotInitialized` struct here would advertise a 1-bit-shorter cell,
// yield a wrong deployment address, and make the child underflow on load.
// ===========================================================================

contract BagItem {
    author: "piracy.ton"
    version: "2.0.0"
    description: "Child contract for one indexed TON Storage bag"

    storage: BagItemData
    storageAtDeployment: BagItemDataNotInitialized
    incomingMessages: BagItemMessage
    thrownErrors: BagError
}

// ===========================================================================
// MESSAGE HANDLING
// ===========================================================================

fun onInternalMessage(in: InMessage) {
    // C4: accept empty-body messages as top-ups (storage-rent recharge) before
    // any other logic. Without this, a recharge would be rejected and the
    // contract could eventually be frozen for non-payment.
    if (in.body.isEmpty()) {
        return;
    }

    // M2: explicit init-state discriminant — `match` on the union tag.
    val data = BagItemData.load();
    match (data) {
        BagItemDataNotInitialized => {
            // Only the parent registry may perform the one-shot init.
            assert (in.senderAddress == data.registryAddress) throw BagError.NotFromRegistry;

            // The init body carries the BagItemInitParams opcode; parsing it
            // also validates that opcode.
            val params = BagItemInitParams.fromSlice(in.body);

            val initialized: BagItemData = BagItemDataInitialized {
                bagIndex: data.bagIndex,
                registryAddress: data.registryAddress,
                bagId: params.bagId,
                name: params.name,
                category: params.category,
                uploaderAddress: params.uploaderAddress,
                timestamp: params.timestamp,
                isActive: true,
                metadata: params.metadata,
            };
            initialized.save();
        }

        BagItemDataInitialized => {
            // Explicit opcode pre-check (surfaces 0xFFFF on unknown bodies).
            // Empty bodies were accepted as top-ups in the early return at
            // the top of `onInternalMessage`.
            assert (in.body.preloadUint(32) == OP_DEACTIVATE_BAG) throw 0xFFFF;
            val _msg = DeactivateBag.fromSlice(in.body);

            assert (in.senderAddress == data.uploaderAddress) throw BagError.NotFromUploader;

            // Idempotency guard: refuse a second deactivation on an already
            // inactive bag. Without this check a re-call would emit a
            // duplicate BagRemovedEvent (confusing indexers) and process a
            // no-op refund (wasting the caller's gas). Throwing 272 reverts
            // the message and bounces the value back to the uploader.
            assert (data.isActive) throw BagError.AlreadyInactive;

            // Flip the active flag and persist.
            var updated = data;
            updated.isActive = false;
            updated.save();

            // Emit the deactivation event. It MUST be queued before the
            // reserve + carry-all-balance refund: a forward fee is paid from
            // the balance, and the mode-128 refund below leaves nothing
            // behind to pay later actions with.
            emitBagRemoved({
                bagIndex: data.bagIndex,
                removedBy: in.senderAddress,
            });

            // H1: reserve a tiny rent floor and refund EVERY remaining
            // nanoton to the uploader. The item stays alive (the index
            // remains on-chain queryable, `isActive == false`), but no
            // residual funds are locked beyond a multi-decade reserve.
            reserveToncoinsOnBalance(DEACTIVATED_FLOOR, RESERVE_MODE_EXACT_AMOUNT);
            val refundMsg = createMessage({
                bounce: BounceMode.NoBounce,
                dest: in.senderAddress,
                // ignored under mode 128 (carry all remaining balance)
                value: 0,
            });
            // SAFETY: mode 128 (carry all remaining balance) runs ONLY after
            // `reserveToncoinsOnBalance(DEACTIVATED_FLOOR, EXACT)` above, so it
            // can never drain the contract below its multi-decade rent floor.
            // Mode 2 (ignore errors) prevents a failed refund action from
            // reverting the already-committed `isActive = false` save + emit.
            // Required invariant: the reserve action must be queued before
            // this send (the action queue is processed in insertion order).
            refundMsg.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
        }
    }
}

// ===========================================================================
// GET METHODS
//
// The getter reply shapes (BagDataReply, StaticDataReply, StorageMetadataReply)
// are declared in `messages.tolk` so generated wrappers can name them.
//
// L3: while uninitialized, getters return clean sentinels — a none-address
// (`createAddressNone()`) and zeros — plus a clear `isInitialized` flag. They
// never substitute the registry address for a missing uploader address.
// ===========================================================================

/// Full identity + status of the bag.
get fun get_bag_data(): BagDataReply {
    val data = BagItemData.load();
    match (data) {
        BagItemDataNotInitialized => {
            return {
                isInitialized: false,
                bagIndex: data.bagIndex,
                registryAddress: data.registryAddress,
                bagId: 0,
                name: createEmptyCell(),
                category: 0,
                uploaderAddress: createAddressNone() as address,
                timestamp: 0,
                isActive: false,
            };
        }
        BagItemDataInitialized => {
            return {
                isInitialized: true,
                bagIndex: data.bagIndex,
                registryAddress: data.registryAddress,
                bagId: data.bagId,
                name: data.name,
                category: data.category,
                uploaderAddress: data.uploaderAddress,
                timestamp: data.timestamp,
                isActive: data.isActive,
            };
        }
    }
}

/// Static identity: (bagIndex, registryAddress). Valid in both states.
get fun get_static_data(): StaticDataReply {
    val data = BagItemData.load();
    match (data) {
        BagItemDataNotInitialized => {
            return { bagIndex: data.bagIndex, registryAddress: data.registryAddress };
        }
        BagItemDataInitialized => {
            return { bagIndex: data.bagIndex, registryAddress: data.registryAddress };
        }
    }
}

/// TON Storage technical metadata of the bag.
get fun get_storage_metadata(): StorageMetadataReply {
    val data = BagItemData.load();
    match (data) {
        BagItemDataNotInitialized => {
            return {
                isInitialized: false,
                description: createEmptyCell(),
                bagSize: 0,
                filesCount: 0,
                files: createEmptyCell(),
                pieceSize: 0,
                merkleHash: 0,
                dirName: createEmptyCell(),
            };
        }
        BagItemDataInitialized => {
            val m = data.metadata.load();
            return {
                isInitialized: true,
                description: m.description,
                bagSize: m.bagSize,
                filesCount: m.filesCount,
                files: m.files,
                pieceSize: m.pieceSize,
                merkleHash: m.merkleHash,
                dirName: m.dirName,
            };
        }
    }
}

/// Whether the bag is currently active. False while uninitialized.
get fun is_active(): bool {
    val data = BagItemData.load();
    return match (data) {
        BagItemDataNotInitialized => false,
        BagItemDataInitialized => data.isActive,
    };
}

// Exit codes thrown by BagRegistry and BagItem.
//
// L1 fix: only codes that are actually thrown remain. Dead constants
// (ERROR_NOT_FROM_OWNER, ERROR_INSUFFICIENT_BALANCE, ERROR_INVALID_INDEX,
// ERROR_ALREADY_INITIALIZED) were removed.
//
// Declared as an `enum` so the `contract` ABI can export `thrownErrors`.
// User exit codes live in the 256..399 range to avoid clashing with TVM
// reserved codes (0..255) and the standard "unknown opcode" code 0xFFFF.

enum BagError {
    // --- BagRegistry ---
    /// Attached value is below MIN_ADD_BAG_VALUE (M6).
    InsufficientValue = 256
    /// `bagId` is zero, which is never a valid TON Storage bag hash.
    InvalidBagId = 257
    /// `category` is outside the supported 0..5 range.
    InvalidCategory = 258
    /// A user-supplied metadata cell exceeds the configured size bounds (M1).
    MetadataTooLarge = 259
    /// `get_bag_address` was called with an index outside [0, nextBagIndex) (L2).
    IndexOutOfRange = 260

    // --- BagItem ---
    /// An init message for a fresh BagItem did not come from its registry.
    NotFromRegistry = 270
    /// A DeactivateBag message did not come from the recorded uploader.
    NotFromUploader = 271
    /// A DeactivateBag message was sent to a bag that was already deactivated.
    /// Prevents a double-emit of BagRemovedEvent and bounces the gas value back
    /// to the uploader instead of silently re-doing the no-op.
    AlreadyInactive = 272
}

// External-out log events for indexers and mirrors.
//
// M4 fix: events are now typed structs emitted with `createExternalLogMessage`
// instead of hand-built `ext_out_msg_info` cells + `sendRawMessage`.
//
// SLIM EVENT (gas optimisation): BagIndexedEvent carries only the fields that
// cannot be re-derived from another on-chain source. The full TON Storage
// metadata is NOT embedded — indexers fetch it on demand via the BagItem's
// `get_storage_metadata`. This roughly halves the external forward fee paid
// per AddBag (fwd fees scale with the cell tree size of the message body).
// ===========================================================================
// EVENT BODIES
//
// Opcodes use the 0x10xxxxxx range to stay clearly distinct from the inbound
// message opcodes ("ASCII" range). They are the first 32 bits of the emitted
// external-out message body, so indexers route purely on the opcode.
// ===========================================================================

/// Emitted by BagRegistry when a new bag is successfully registered.
///
/// Indexer flow: filter on `bagId` / `category` / `uploader` from this event,
/// then call `get_storage_metadata` on the BagItem (whose address derives from
/// `bagIndex`) for the full TON Storage technical metadata.
struct (0x10000001) BagIndexedEvent {
    /// Sequential index assigned in the registry. Used to derive the BagItem
    /// address via the registry's `get_bag_address(bagIndex)`.
    bagIndex: uint64
    /// TON Storage bag hash.
    bagId: uint256
    /// Category id, 0..5.
    category: uint8
    /// Wallet that registered the bag.
    uploader: address
    /// Registration time (Unix seconds), as recorded by the registry.
    timestamp: uint64
    /// Bag display name as a direct ref, so indexers can label entries without
    /// an extra RPC. Snake-format string cell.
    name: cell
}

/// Emitted by a BagItem when its uploader deactivates it.
struct (0x10000002) BagRemovedEvent {
    /// Sequential index of the deactivated bag.
    bagIndex: uint64
    /// Address that triggered the deactivation (always the uploader).
    removedBy: address
}

/// Union of every external-out event this project emits (for ABI export).
type BagEvent = BagIndexedEvent | BagRemovedEvent

// ===========================================================================
// EMIT HELPERS
// ===========================================================================

/// Emit a BagIndexed event. `dest` is the "none" external address; indexers
/// route on the 32-bit opcode prefix of the body.
fun emitBagIndexed(ev: BagIndexedEvent) {
    val msg = createExternalLogMessage({
        dest: createAddressNone(),
        body: ev,
    });
    msg.send(SEND_MODE_REGULAR);
}

/// Emit a BagRemoved event.
fun emitBagRemoved(ev: BagRemovedEvent) {
    val msg = createExternalLogMessage({
        dest: createAddressNone(),
        body: ev,
    });
    msg.send(SEND_MODE_REGULAR);
}

// Message bodies for BagRegistry and BagItem.
//
// M3 fix: every on-chain message is a struct with an explicit 32-bit opcode,
// grouped into a union and routed with `match` in the entrypoints.
//
// M1 fix (schema margin): the original AddBag carried `name`, `description`,
// `files` and `dirName` as four top-level refs — exactly the 4-ref cell cap,
// leaving zero room to ever extend the schema. The TON Storage technical
// fields are now nested into a single `Cell<BagMetadata>` ref, so AddBag and
// BagItemInitParams each use only 2 refs and stay extensible.
// ===========================================================================
// SHARED PAYLOAD TYPES
// ===========================================================================

/// TON Storage technical metadata for a bag. Carried as one ref (`Cell<...>`)
/// inside AddBag, the init params and the on-chain BagItem storage.
struct BagMetadata {
    /// Human-readable description, snake-format string cell.
    description: cell
    /// Total bag size in bytes.
    bagSize: uint64
    /// Number of files in the bag.
    filesCount: uint32
    /// Dictionary cell: file index -> (name, size).
    files: cell
    /// TON Storage piece size used for transfers.
    pieceSize: uint32
    /// Merkle root hash for integrity verification.
    merkleHash: uint256
    /// Root directory name, snake-format string cell.
    dirName: cell
}

// ===========================================================================
// REGISTRY -> ITEM : deploy / init params
// ===========================================================================

/// Body of the deploy message sent by BagRegistry to a fresh BagItem.
///
/// Opcode 0x42495F49 = "BI_I" (Bag Item Init). A dedicated opcode lets the
/// BagItem reject any non-init traffic that reaches it while uninitialized.
struct (0x42495F49) BagItemInitParams {
    /// TON Storage bag hash.
    bagId: uint256
    /// Category id, 0..5 (validated by the registry before deploy).
    category: uint8
    /// Wallet that registered the bag (refunded surplus is unrelated; this is
    /// just provenance). Becomes the only address allowed to deactivate.
    uploaderAddress: address
    /// Registration time (registry block time).
    timestamp: uint64
    /// Bag display name, snake-format string cell.
    name: cell
    /// TON Storage technical metadata, one ref.
    metadata: Cell<BagMetadata>
}

// ===========================================================================
// MESSAGES TO BAG REGISTRY
// ===========================================================================

/// Register a new bag. Permissionless: anyone may send it; the sender only
/// pays gas + child funding and is refunded the surplus (C3).
///
/// Opcode 0x41444247 = "ADBG" (ADd BaG).
struct (0x41444247) AddBag {
    /// TON Storage bag hash. Must be non-zero.
    bagId: uint256
    /// Category id, 0..5.
    category: uint8
    /// Bag display name, snake-format string cell.
    name: cell
    /// TON Storage technical metadata, one ref.
    metadata: Cell<BagMetadata>
}

/// Union of every internal message BagRegistry accepts.
type BagRegistryMessage = AddBag

// ===========================================================================
// MESSAGES TO BAG ITEM
// ===========================================================================

/// Deactivate a bag. Only the recorded uploader may send it.
///
/// Opcode 0x44454143 = "DEAC" (DEACtivate).
struct (0x44454143) DeactivateBag {}

/// Union of every internal message a fully initialized BagItem accepts.
/// (The one-shot init message uses the BagItemInitParams opcode separately.)
type BagItemMessage = DeactivateBag

// ===========================================================================
// BAG ITEM GETTER REPLY SHAPES
//
// These are pure data shapes returned by the BagItem get-methods. They live
// here (not in BagItem.tolk) so generated wrappers — which import only
// `messages` and `storage` — can name the getter return types. L3: while
// uninitialized, getters return clean sentinels rather than placeholder data.
// ===========================================================================

/// Identity + status reply for a bag.
struct BagDataReply {
    /// Whether the bag has been initialized by the registry.
    isInitialized: bool
    /// Sequential registry index (valid in both states).
    bagIndex: uint64
    /// Parent registry address (valid in both states).
    registryAddress: address
    /// TON Storage bag hash (0 while uninitialized).
    bagId: uint256
    /// Bag display name cell (empty cell while uninitialized).
    name: cell
    /// Category id (0 while uninitialized).
    category: uint8
    /// Uploader wallet (none-address while uninitialized).
    uploaderAddress: address
    /// Registration time (0 while uninitialized).
    timestamp: uint64
    /// Active status (false while uninitialized).
    isActive: bool
}

/// Static identity: (bagIndex, registryAddress). Valid in both states.
struct StaticDataReply {
    bagIndex: uint64
    registryAddress: address
}

/// TON Storage technical metadata of the bag.
struct StorageMetadataReply {
    /// True when the bag is initialized; the remaining fields are sentinels
    /// (empty cells / zeros) when false.
    isInitialized: bool
    description: cell
    bagSize: uint64
    filesCount: uint32
    files: cell
    pieceSize: uint32
    merkleHash: uint256
    dirName: cell
}

// Persistent on-chain storage layouts for BagRegistry and BagItem.

import "messages.tolk"

// ===========================================================================
// BAG REGISTRY STORAGE (master, owner-less)
//
// C2 note: `nextBagIndex` only ever increases. It is NEVER decremented — see
// BagRegistry.tolk. A failed child deploy leaves a benign "phantom" index;
// indexers skip it via the BagItem `isInitialized` flag.
//
// The BagItem code is embedded into BagRegistry at compile time
// (`@gen/BagItem.code`), so it is intentionally NOT a storage field. This
// removes the old `bagItemCode: cell` field, makes the code immutable, and
// shrinks the master storage to a single counter.
// ===========================================================================

struct BagRegistryStorage {
    /// Index that will be assigned to the next registered bag. Starts at 0.
    nextBagIndex: uint64 = 0
}

fun BagRegistryStorage.load(): BagRegistryStorage {
    return BagRegistryStorage.fromCell(contract.getData());
}

fun BagRegistryStorage.save(self) {
    contract.setData(self.toCell());
}

// ===========================================================================
// BAG ITEM STORAGE (child)
//
// M2 fix: the old design detected init state with a fragile
// `remainingRefsCount()` heuristic. It is replaced by an EXPLICIT 1-bit
// discriminant: `BagItemData` is a union of two structs with no manual
// opcodes, so the compiler emits an `Either` prefix (`0` => NotInitialized,
// `1` => Initialized). The registry serializes the NotInitialized variant at
// deploy time; the BagItem routes on the tag with `match`.
// ===========================================================================

/// Pre-init shape: what the registry writes into a fresh BagItem's data so the
/// item's address is deterministically derivable from (code, index, registry).
struct BagItemDataNotInitialized {
    /// Sequential index assigned by the registry.
    bagIndex: uint64
    /// Parent registry address; the only sender allowed to initialize.
    registryAddress: address
}

/// Fully initialized shape: written once when the registry's init message is
/// processed. From then on the storage stays in this variant forever.
struct BagItemDataInitialized {
    /// Sequential index assigned by the registry.
    bagIndex: uint64
    /// Parent registry address.
    registryAddress: address
    /// TON Storage bag hash.
    bagId: uint256
    /// Bag display name, snake-format string cell.
    name: cell
    /// Category id, 0..5.
    category: uint8
    /// Wallet that registered the bag; only it may deactivate.
    uploaderAddress: address
    /// Registration time (Unix seconds).
    timestamp: uint64
    /// Whether the bag is currently active.
    isActive: bool
    /// TON Storage technical metadata, one ref.
    metadata: Cell<BagMetadata>
}

/// Explicit init-state discriminant. Auto-generated 1-bit `Either` prefix:
///   tag 0 -> BagItemDataNotInitialized
///   tag 1 -> BagItemDataInitialized
type BagItemData = BagItemDataNotInitialized | BagItemDataInitialized

/// Serialize a `BagItemData` value WITH its 1-bit `Either` discriminant.
///
/// This indirection is required for correctness. When `.toCell()` is invoked on
/// a value whose *static* type the compiler has narrowed to a single variant
/// (e.g. `val d: BagItemData = BagItemDataNotInitialized { ... }`), the compiler
/// emits the *bare struct* layout with NO discriminant. `BagItemData.fromCell()`
/// always reads the discriminant, so a bare cell makes it underflow (exit 9).
///
/// Routing the value through a parameter typed as the union forces the compiler
/// to emit the discriminant-bearing union layout, so `toCell`/`fromCell` stay
/// round-trip compatible regardless of how the caller built the value.
fun serializeBagItemData(data: BagItemData): cell {
    return data.toCell();
}

fun BagItemData.load(): BagItemData {
    return BagItemData.fromCell(contract.getData());
}

fun BagItemData.save(self) {
    contract.setData(serializeBagItemData(self));
}

// ===========================================================================
// CHILD ADDRESS DERIVATION
//
// The registry derives a child's address from (BagItem code, deterministic
// pre-init data). The pre-init data MUST be the NotInitialized variant so its
// 1-bit discriminant is `0`; this keeps the address stable and lets the child
// recognize its own uninitialized state.
// ===========================================================================

/// Build the AutoDeployAddress of the BagItem for `bagIndex`, given the
/// registry address and the (compile-time embedded) BagItem code.
fun calcDeployedBagItem(
    bagIndex: uint64,
    registryAddress: address,
    bagItemCode: cell,
): AutoDeployAddress {
    val preInitData: BagItemData = BagItemDataNotInitialized { bagIndex, registryAddress };
    // Serialize via the union-typed helper so the `Either` discriminant (tag 0)
    // is written. A bare `preInitData.toCell()` would omit it and the child's
    // `BagItemData.load()` would underflow on first message (exit 9).
    return { stateInit: { code: bagItemCode, data: serializeBagItemData(preInitData) } };
}
